"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["39216"],{78743(e,a,t){t.r(a),t.d(a,{metadata:()=>n,default:()=>l,frontMatter:()=>p,contentTitle:()=>c,toc:()=>h,assets:()=>d});var n=JSON.parse('{"id":"nhcx/v1/api/adjudicator/endpoints/adjudicator-update-abhanumber","title":"Update ABHA number","description":"Replaces a placeholder (dummy) ABHA number with the beneficiary\'s real ABHA number in the ABHA_AUTH_TRANSACTION table.","source":"@site/docs/nhcx/v1/api/adjudicator/endpoints/adjudicator-update-abhanumber.mdx","sourceDirName":"nhcx/v1/api/adjudicator/endpoints","slug":"/nhcx/v1/api/adjudicator/endpoints/adjudicator-update-abhanumber","permalink":"/docs/pr-45/docs/nhcx/v1/api/adjudicator/endpoints/adjudicator-update-abhanumber","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Update ABHA number","sidebar_label":"Update ABHA number","sidebar_class_name":"api-method api-method--post","description":"Replaces a placeholder (dummy) ABHA number with the beneficiary\'s real ABHA number in the ABHA_AUTH_TRANSACTION table.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-adjudicator.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Adjudicator: act on a case","permalink":"/docs/pr-45/docs/nhcx/v1/api/adjudicator/endpoints/adjudicator-pmjay-hcx-nhcxpayerservice-wrapper-process-case"},"next":{"title":"Overview","permalink":"/docs/pr-45/docs/nhcx/v1/api/biometric/"}}'),r=t(62540),s=t(43023),i=t(85030),o=JSON.parse('{"id":"adjudicator_update_abhanumber","module":"PMJAY adjudicator","moduleId":"adjudicator","kind":"operation","method":"POST","path":"/update/abhanumber","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Update ABHA number","title":"Update ABHA number","description":"Replaces a placeholder (dummy) ABHA number with the beneficiary\'s real ABHA number in the ABHA_AUTH_TRANSACTION table.\\n\\n### Business purpose\\n\\nBeneficiaries are sometimes onboarded before their real ABHA is known, using a placeholder value. Because the member layer and the Patient resource both key on the ABHA number, a placeholder that is never corrected leaves the beneficiary undiscoverable and breaks the identifier rules for claim bundles. This endpoint, tagged Retrieving API and implemented by updateAbhaNumberController, lets the placeholder be swapped for the real number so that later policy lookups and claim transactions line up. The docs describe it as updating the ABHA number in the ABHA_AUTH_TRANSACTION table.\\n\\n### When to use\\n\\nUse it when a member\'s real ABHA number becomes available after they were set up with a placeholder. Do it before you rely on ABHA-based lookups.\\n\\n### Preconditions\\n\\n- You have a valid access token in the `bearer_auth` header.\\n- You know both the placeholder and the real ABHA number.\\n\\n### Postconditions\\n\\nThe member\'s ABHA number is updated. Errors come back in the same response shape as success, so read `errorMessage`.\\n\\n### Common mistakes\\n\\n- Reading errors as the usual registry error format.\\n- Sending an empty body.\\n- Forgetting to refresh cached policies that still use the placeholder.\\n\\n### Best practices\\n\\n- Record both the placeholder and the real ABHA with the timestamp of the change for audit purposes.\\n- Read successMessage and errorMessage on every response and treat a non-200 status as failure even if the body parses.\\n- Immediately re-run /participant/get/policies with forceRefresh: true for the affected beneficiary.\\n- Keep the ABHA formatting rule per field: hyphen-free for member lookups and x-hcx-ben-ABHA-ID, XX-XXXX-XXXX-XXXX where NHCX-1018 applies.\\n- Never log the token; log the ABHA change with the request identifier only.\\n\\n### Related scenario\\n\\nA state scheme enrols a beneficiary in a hurry with a dummy ABHA so that a policy can be linked and an emergency admission can proceed. After discharge the beneficiary completes ABHA creation and the real number is captured. The payer\'s system calls /update/abhanumber with dummyAbha and realAbha, receives a successMessage, and then calls /participant/get/policies with forceRefresh to make sure the real ABHA resolves the linked product. The hospital\'s billing team, preparing the final claim, refreshes its own policy cache so that the Claim bundle\'s Patient identifiers carry the PMJAY member ID and the real hyphen-free ABHA.\\n\\n### Specification\\n\\nChapter [Participants and policies](/docs/nhcx/v1/registries) of the NHCX integration specification.","gateway":"nhcx","security":[{"name":"bearerAuth","type":"apiKey","in":"header","headerName":"bearer_auth","description":"Every NHCX call carries the access token from the session call in a header named `bearer_auth`, as the word `Bearer`, a space and the token. NHCX reads `bearer_auth`, not `Authorization`.","example":"Bearer <access token>","prefix":"Bearer "}],"headers":[{"name":"Accept","required":true,"description":"Always `application/json` on the payer service.","example":"application/json","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"dummyAbha","type":"string","required":false,"description":"","encrypted":false},{"name":"realAbha","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"dummyAbha":"99999999999999","realAbha":"12345678910111"},"responses":[{"status":"200","description":"A successful call returns HTTP 200 with UpdateAbhaResponse, which carries optional successMessage and errorMessage strings.","example":{"successMessage":"ABHA number updated successfully"},"synthesised":false,"fields":[{"name":"successMessage","type":"string","required":false,"description":""}]}],"tag":"PMJAY payer APIs","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/update/abhanumber \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Accept: application/json\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"dummyAbha\\": \\"99999999999999\\",\\n  \\"realAbha\\": \\"12345678910111\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/update/abhanumber \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Accept: application/json\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"dummyAbha\\": \\"99999999999999\\",\\n  \\"realAbha\\": \\"12345678910111\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/update/abhanumber\\",\\n    headers={\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Accept\\": \\"application/json\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"dummyAbha\\": \\"99999999999999\\",\\n        \\"realAbha\\": \\"12345678910111\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node.js","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/update/abhanumber\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Accept\\": \\"application/json\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"dummyAbha\\": \\"99999999999999\\",\\n    \\"realAbha\\": \\"12345678910111\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"},{"id":"java","label":"Java","language":"java","code":"import java.net.URI;\\nimport java.net.http.HttpClient;\\nimport java.net.http.HttpRequest;\\nimport java.net.http.HttpResponse;\\n\\nHttpClient client = HttpClient.newHttpClient();\\nHttpRequest request = HttpRequest.newBuilder()\\n    .uri(URI.create(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/update/abhanumber\\"))\\n    .header(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n    .header(\\"Accept\\", \\"application/json\\")\\n    .header(\\"Content-Type\\", \\"application/json\\")\\n    .method(\\"POST\\", HttpRequest.BodyPublishers.ofString(\\"\\"\\"\\n        {\\n            \\"dummyAbha\\": \\"99999999999999\\",\\n            \\"realAbha\\": \\"12345678910111\\"\\n        }\\n        \\"\\"\\"))\\n    .build();\\n\\nHttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());\\nSystem.out.println(response.statusCode() + \\" \\" + response.body());"},{"id":"php","label":"PHP","language":"php","code":"<?php\\n\\n$ch = curl_init(\'https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/update/abhanumber\');\\ncurl_setopt_array($ch, [\\n    CURLOPT_CUSTOMREQUEST => \'POST\',\\n    CURLOPT_RETURNTRANSFER => true,\\n    CURLOPT_HTTPHEADER => [\\n        \'bearer_auth: Bearer <access token>\',\\n        \'Accept: application/json\',\\n        \'Content-Type: application/json\',\\n    ],\\n    CURLOPT_POSTFIELDS => <<<\'JSON\'\\n    {\\n        \\"dummyAbha\\": \\"99999999999999\\",\\n        \\"realAbha\\": \\"12345678910111\\"\\n    }\\n    JSON,\\n]);\\n\\n$response = curl_exec($ch);\\necho curl_getinfo($ch, CURLINFO_HTTP_CODE), \' \', $response, PHP_EOL;"},{"id":"go","label":"Go","language":"go","code":"package main\\n\\nimport (\\n\\t\\"fmt\\"\\n\\t\\"io\\"\\n\\t\\"net/http\\"\\n\\t\\"strings\\"\\n)\\n\\nfunc main() {\\n\\tbody := strings.NewReader(`{\\n  \\"dummyAbha\\": \\"99999999999999\\",\\n  \\"realAbha\\": \\"12345678910111\\"\\n}`)\\n\\treq, err := http.NewRequest(\\"POST\\", \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/update/abhanumber\\", body)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\treq.Header.Set(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n\\treq.Header.Set(\\"Accept\\", \\"application/json\\")\\n\\treq.Header.Set(\\"Content-Type\\", \\"application/json\\")\\n\\n\\tresp, err := http.DefaultClient.Do(req)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\tdefer resp.Body.Close()\\n\\tout, _ := io.ReadAll(resp.Body)\\n\\tfmt.Println(resp.StatusCode, string(out))\\n}"},{"id":"csharp","label":"C#","language":"csharp","code":"using var client = new HttpClient();\\nvar request = new HttpRequestMessage(new HttpMethod(\\"POST\\"), \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/update/abhanumber\\");\\nrequest.Headers.TryAddWithoutValidation(\\"bearer_auth\\", \\"Bearer <access token>\\");\\nrequest.Headers.TryAddWithoutValidation(\\"Accept\\", \\"application/json\\");\\nrequest.Content = new StringContent(\\"\\"\\"\\n    {\\n        \\"dummyAbha\\": \\"99999999999999\\",\\n        \\"realAbha\\": \\"12345678910111\\"\\n    }\\n    \\"\\"\\", System.Text.Encoding.UTF8, \\"application/json\\");\\n\\nvar response = await client.SendAsync(request);\\nConsole.WriteLine($\\"{(int)response.StatusCode} {await response.Content.ReadAsStringAsync()}\\");"},{"id":"ruby","label":"Ruby","language":"ruby","code":"require \'net/http\'\\n\\nuri = URI(\'https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/update/abhanumber\')\\nrequest = Net::HTTP::Post.new(uri)\\nrequest[\'bearer_auth\'] = \'Bearer <access token>\'\\nrequest[\'Accept\'] = \'application/json\'\\nrequest[\'Content-Type\'] = \'application/json\'\\nrequest.body = <<~\'JSON\'\\n  {\\n    \\"dummyAbha\\": \\"99999999999999\\",\\n    \\"realAbha\\": \\"12345678910111\\"\\n  }\\nJSON\\n\\nresponse = Net::HTTP.start(uri.hostname, uri.port, use_ssl: uri.scheme == \'https\') do |http|\\n  http.request(request)\\nend\\nputs response.code, response.body"}]}');let p={title:"Update ABHA number",sidebar_label:"Update ABHA number",sidebar_class_name:"api-method api-method--post",description:"Replaces a placeholder (dummy) ABHA number with the beneficiary's real ABHA number in the ABHA_AUTH_TRANSACTION table.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-adjudicator.yaml",generated:!0},c,d={},h=[];function u(e){return(0,r.jsx)(i.A,{operation:o})}function l(e={}){let{wrapper:a}={...(0,s.R)(),...e.components};return a?(0,r.jsx)(a,{...e,children:(0,r.jsx)(u,{...e})}):u(e)}}}]);